namespace Sigloc.Application.Contracts;

/// <summary>
/// Opaque binary storage. Keys are generated by the storage and are the only handle callers keep;
/// they never contain client-supplied names.
/// </summary>
public interface IFileStorage
{
    /// <summary>Stores <paramref name="content"/> under a new key below <paramref name="prefix"/>.</summary>
    Task<string> SaveAsync(string prefix, Stream content, string extension, CancellationToken ct = default);

    /// <summary>Opens a stored file for reading, or returns null when the key does not exist.</summary>
    Task<Stream?> OpenReadAsync(string key, CancellationToken ct = default);

    Task DeleteAsync(string key, CancellationToken ct = default);
}
